    internal static partial class NativeTests {
        static int passed;static string root;
        static void Check(bool value,string name) {if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
        static void Reject(Action action,string name) {try{action();}catch{Check(true,name);return;}throw new Exception("FAIL: accepted "+name);}
        static async Task RejectAsync(Func<Task> action,string name) {try{await action();}catch{Check(true,name);return;}throw new Exception("FAIL: accepted "+name);}
        static Vault Create(string name) {var v=new Vault(Path.Combine(root,name),null);v.State["workspace"]=Path.Combine(root,name,"work");Directory.CreateDirectory(J.Str(v.State,"workspace"));v.Save();return v;}
        [STAThread] public static int Main(string[] args) {try{if(args.Contains("--mcp-demo")){McpDemo(args[1],args.Contains("--controller"));return 0;}Console.InputEncoding=new System.Text.UTF8Encoding(false);Console.OutputEncoding=new System.Text.UTF8Encoding(false);if(args.Contains("--inspect-package")){InspectPackage(args[1]);return 0;}if(args.Contains("--live-screen-type")){LiveScreenType(args[1],args[2],args[3]).GetAwaiter().GetResult();return 0;}if(args.Contains("--live-lan")){LiveLan(args[1],args[2],args[3],args.Contains("--direct")?args[4]:null,args.Contains("--screen-home"),args.Contains("--hold-session")).GetAwaiter().GetResult();return 0;}if(args.Contains("--live-chatgpt")){LiveChatGPT(args[1],args[2],args.Contains("--exclusive-refresh")).GetAwaiter().GetResult();return 0;}if(args.Contains("--auth-network")){PublicAuthCheck().GetAwaiter().GetResult();return 0;}if(args.Contains("--brand-layout")){BrandLayout(args[1]);return 0;}if(args.Contains("--layout-unaware")){Layout(args[1],false);return 0;}if(args.Contains("--layout")){Layout(args[1]);return 0;}if(args.Contains("--interop")){Interop();return 0;}Run().GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e.ToString());return 1;}}
        static void Interop() {var p=J.Read(Console.In.ReadToEnd());string op=J.Str(p,"op");object result;if(op=="seal")result=Wire.Seal(J.Str(p,"pair"),J.Str(p,"key"),J.Get(p,"payload"),J.Str(p,"direction"));else if(op=="open")result=Wire.Open(J.Get(p,"packet"),J.Str(p,"key"),J.Str(p,"direction"));else if(op=="pair")result=J.Obj("key",Wire.PairKey(J.Get(p,"identity"),J.Get(p,"remote"),J.Str(p,"id")));else if(op=="identity")result=Wire.NewIdentity();else if(op=="frame")result=J.Obj("data",Convert.ToBase64String(Wire.Frame(J.Str(p,"key"),J.Str(p,"nonce"),1,Wire.Utf8("fixture-jpeg"),100,200)));else throw new Exception("Unknown interop operation");Console.WriteLine(J.Write(result));}
        static async Task Run() {root=Path.Combine(Path.GetTempPath(),"AsterHand-native-tests-"+J.Id());Directory.CreateDirectory(root);string key=Wire.Hex(Wire.Random(32)),pair=J.Id();var payload=J.Obj("id",J.Id(),"ts",J.Now,"text","中文 🔐");var sealedPacket=Wire.Seal(pair,key,payload,"req");Check(J.Str(Wire.Open(sealedPacket,key,"req"),"text")=="中文 🔐","AES-CBC/HMAC Unicode roundtrip");Reject(()=>Wire.Open(sealedPacket,key,"res"),"direction separation");var modified=J.Read(J.Write(sealedPacket));modified["data"]=J.Str(modified,"data").Replace('A','B')+"AA";Reject(()=>Wire.Open(modified,key,"req"),"MAC tampering rejected");Reject(()=>Wire.Open(Wire.Seal(pair,key,J.Obj("id","nan","ts","NaN"),"req"),key,"req"),"non-finite wire timestamp rejected");Reject(()=>Wire.Open(Wire.Seal(pair,key,J.Obj("id","expired","ts",J.Now-100),"req"),key,"req"),"expired packet rejected");uint seq=0;var video=Wire.Frame(key,pair,1,Wire.Utf8("fixture-jpeg"),100,200);Check(System.Text.Encoding.UTF8.GetString(Wire.OpenFrame(key,pair,video,ref seq))=="fixture-jpeg","authenticated frame roundtrip");Reject(()=>{uint replay=1;Wire.OpenFrame(key,pair,video,ref replay);},"video replay rejected");var a=Wire.NewIdentity();var b=Wire.NewIdentity();var aid=J.Obj("public_key",J.Str(a,"public_key"),"device_id",Wire.Hex(Wire.Hash(Wire.Decode(J.Str(a,"public_key")))));var bid=J.Obj("public_key",J.Str(b,"public_key"),"device_id",Wire.Hex(Wire.Hash(Wire.Decode(J.Str(b,"public_key")))));Check(Wire.PairKey(a,bid,pair)==Wire.PairKey(b,aid,pair),"P-256 ECDH agreement");bid["device_id"]=new string('0',64);Reject(()=>Wire.PairKey(a,bid,pair),"device identity hash mismatch rejected");
            var vault=Create("vault");vault.State["key"]="fixture-secret-key";vault.Save();Check(!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(vault.DirectoryPath,"settings.dat"))).Contains("fixture-secret-key"),"DPAPI encrypts saved credentials");var reload=new Vault(vault.DirectoryPath,null);Check(J.Str(reload.State,"key")=="fixture-secret-key","DPAPI credential readback");Check(File.Exists(Path.Combine(vault.DirectoryPath,"settings.dat.bak")),"atomic configuration backup");var projects=new ProjectStore(Path.Combine(root,"projects"));var project=projects.Create("测试 project","C:\\fixture");var chat=projects.NewChat(project);chat["draft"]="保留草稿";projects.Save();var projectsReload=new ProjectStore(projects.Root);Check(J.Str(J.List(J.Get(projectsReload.Projects.Last(),"chats")).First(),"draft")=="保留草稿","project/chat/draft persistence");
            using(var tools=new ToolHost(vault)){await tools.Execute("write_file",J.Obj("path","fixture.txt","content","你好\nfixture"),CancellationToken.None);await tools.Execute("write_file",J.Obj("path","fixture.txt","content","changed"),CancellationToken.None);Check(Directory.GetFiles(tools.Work,"fixture.txt.asterhand-backup-*").Length==1,"file overwrite preserves backup");var read=await tools.Execute("read_file",J.Obj("path","fixture.txt","offset",2),CancellationToken.None);Check(J.Str(read,"text")=="anged","file byte offset");await RejectAsync(()=>tools.Execute("read_file",J.Obj("path","fixture.txt","offset",-1),CancellationToken.None),"negative file offset rejected");await RejectAsync(()=>tools.Execute("screen_capture",J.Obj(),CancellationToken.None),"screen access requires explicit setting");var command=await TerminalSession.Command("Write-Output 'native-command-ok'",tools.Work,10,CancellationToken.None);Check(J.Str(command,"output").Contains("native-command-ok")&&J.Num(command,"exit_code")==0,"real PowerShell command");using(var cancel=new CancellationTokenSource(200)){var cancelled=await TerminalSession.Command("Start-Sleep -Seconds 20",tools.Work,30,cancel.Token);Check(J.Bool(cancelled,"cancelled"),"command cancellation terminates process tree");}var opened=tools.Terminal("open",J.Obj(),"test");string sid=J.Str(opened,"session");tools.Terminal("write",J.Obj("session",sid,"text","$nativeVar='persistent-ok'\n"),"test");tools.Terminal("write",J.Obj("session",sid,"text","Write-Output $nativeVar\n"),"test");string text="";for(int i=0;i<50&&!text.Contains("persistent-ok");i++){await Task.Delay(100);text=J.Str(tools.Terminal("read",J.Obj("session",sid,"offset",0),"test"),"output");}Check(text.Contains("persistent-ok"),"persistent terminal retains variables");Reject(()=>tools.Terminal("read",J.Obj("session",sid),"other"),"terminal ownership enforced");tools.Terminal("close",J.Obj("session",sid),"test");Reject(()=>tools.Terminal("read",J.Obj("session",sid),"test"),"closed terminal rejected");}
            var v1=Create("sender");var v2=Create("receiver");using(var t1=new ToolHost(v1))using(var t2=new ToolHost(v2))using(var h1=new DeviceHub(v1,t1,0))using(var h2=new DeviceHub(v2,t2,0)){var remote=await h1.DeviceAt("127.0.0.1",h2.Port,CancellationToken.None);var request=await h1.Begin(remote,CancellationToken.None);Check(J.Str(request,"status")=="pending"&&h2.Pending().Length==1,"encrypted pairing waits for receiver consent");h2.Decide(J.Str(request,"id"),"once");var accepted=await h1.Poll(J.Str(request,"id"),false,CancellationToken.None);Check(J.Str(accepted,"status")=="accepted","receiver accepts one-time session");string id=J.Str(accepted,"id");var info=await h1.Request(id,"info",J.Obj(),CancellationToken.None);Check(J.Str(info,"platform")=="win32","encrypted RPC device info");await h1.Request(id,"execute",J.Obj("tool","write_file","arguments",J.Obj("path","rpc.txt","content","encrypted-rpc-ok")),CancellationToken.None);Check(File.ReadAllText(Path.Combine(t2.Work,"rpc.txt"))=="encrypted-rpc-ok","encrypted RPC file operation");await RejectAsync(()=>h2.Request(id,"execute",J.Obj("tool","list_directory","arguments",J.Obj("path",".")),CancellationToken.None),"outgoing pairing grants no reverse control");h2.Revoke(id);await RejectAsync(()=>h1.Request(id,"info",J.Obj(),CancellationToken.None),"revoked peer refused");}
            var chatBody=J.Obj("model","fixture","instructions","fixture","tools",new object[0],"input",new object[]{J.Obj("role","user","content",new[]{J.Obj("type","input_text","text","hello")}),J.Obj("type","function_call","call_id","call-1","name","read_file","arguments","{}"),J.Obj("type","function_call_output","call_id","call-1","output","fixture-output")});Check(J.List(J.Get(Agent.ChatBody(chatBody),"messages")).Count==4,"Chat Completions tool conversion");Reject(()=>Agent.ChatResponse(J.Obj("choices",new[]{J.Obj("finish_reason","length","message",J.Obj("content","truncated"))})),"incomplete model output rejected");Reject(()=>Net.Api("https://user:secret@example.com/v1","models"),"credential-bearing API URL rejected");Reject(()=>Net.Api("http://example.com/v1","models"),"plaintext remote API refused");Check(Net.Api("http://127.0.0.1:11434/v1","models").IsLoopback,"local model HTTP permitted");
            using(var tool=new ToolHost(vault))using(var hub=new DeviceHub(vault,tool,0,false)){var agent=new Agent(vault,tool,hub,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Resources"));int rounds=0;agent.RequestOverride=(body,ct)=>Task.FromResult(rounds++==0?J.Obj("status","completed","output",new[]{J.Obj("type","function_call","call_id","fixture-call","name","write_file","arguments",J.Write(J.Obj("path","never-written.txt","content","not allowed")))}):J.Obj("status","completed","output",new[]{J.Obj("type","message","role","assistant","content",new[]{J.Obj("type","output_text","text","Rejected as requested.")})}));agent.Approve=(name,arguments,target,ct)=>Task.FromResult(false);var history=Agent.Input("fixture",new object[0]);await agent.Run(history,J.Obj("model","fixture","key","fixture"),"local",CancellationToken.None);Check(rounds==2&&!File.Exists(Path.Combine(tool.Work,"never-written.txt"))&&J.Write(history).Contains("User rejected"),"agent rejection returns to model without executing tool");}
            RemoteScreenGeometry();DefaultNames();await AuthTests();await HttpTests();J.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"native-test-report.json"),J.Obj("passed",passed,"failed",0,"timeUtc",DateTime.UtcNow.ToString("o"),"dataDirectory",root,"platform",Environment.OSVersion.ToString(),"win7Verified",false));Console.WriteLine("RESULT: "+passed+" passed; 0 failed");}
    }
